import java.util.Scanner;

public class Main {
    static long n;
    static long[] A = new long[20];
    static long[] B = new long[20];
    static long minimal;

    static void explore(int position, long current_value, long total_cost) {
        if (total_cost >= minimal) return;
        if (position == 0) {
            if (current_value == 0) {
                minimal = total_cost;
            }
            return;
        }
        long quotient = current_value / A[position];
        long delta_neg = Math.abs(quotient) - 1;
        if (quotient < 0) delta_neg = -delta_neg;
        long delta_pos = Math.abs(quotient) + 1;
        if (quotient < 0) delta_pos = -delta_pos;

        explore(position - 1, current_value - quotient * B[position], total_cost + Math.abs(quotient) * position);
        explore(position - 1, current_value - delta_neg * B[position], total_cost + Math.abs(delta_neg) * position);
        explore(position - 1, current_value - delta_pos * B[position], total_cost + Math.abs(delta_pos) * position);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i=1; i<=16; i++) B[i] = B[i-1]*10 + 1;
        A[1] = 1;
        for (int i=2; i<=16; i++) A[i] = A[i-1]*10;
        n = sc.nextLong();
        long temp_num = n;
        int digit_count = 0;
        while (temp_num != 0) {
            digit_count++;
            temp_num /= 10;
        }
        minimal = Long.MAX_VALUE;
        explore(digit_count, n, 0);
        explore(digit_count, B[digit_count+1] - n, digit_count+1);
        System.out.println(minimal);
        sc.close();
    }
}
